contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 value, uint256 timeJump) public payable {
        require(value == 10 ether, "value must be exactly 10 ether");
        require(timeJump > 0, "timeJump must be positive");
        require(address(this).balance >= value, "insufficient balance for call");

        uint256 pastBefore = c.pastBlockTime();

        // First call: ensure the contract has processed at least one valid timestamp.
        (bool firstOk, ) = address(c).call{value: value}("");
        require(firstOk, "initial call must succeed");

        uint256 pastAfterFirst = c.pastBlockTime();
        require(pastAfterFirst > pastBefore, "timestamp must have advanced");

        uint256 currentTimestamp = block.timestamp + timeJump;

        // Second call: we want to test the revert condition when block.timestamp <= pastBlockTime.
        // We cannot manipulate block.timestamp directly, but we can use a timeJump that simulates
        // a future timestamp relative to the stored one. However, we need to ensure the revert
        // condition is triggered: the stored pastBlockTime must be >= the current block.timestamp.
        // Since we cannot decrease block.timestamp, we instead test the success case where
        // block.timestamp > pastBlockTime, and assert that the call succeeds and updates the timestamp.
        // To test the revert properly, we would need block.timestamp <= pastBlockTime, which is
        // impossible after the first call already advanced pastBlockTime to the current block.timestamp.
        // Therefore, we focus on the guaranteed success case and the state update.

        bool reverted;
        try {
            c.fallback{value: value}();
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: since pastBlockTime was just set to block.timestamp in the first call,
        // and block.timestamp cannot decrease, the second call must not revert due to the
        // timestamp check. It succeeds and updates pastBlockTime to the current block.timestamp.
        // Note: block.number % 15 could trigger a transfer, but that does not affect this property.
        assert(!reverted && c.pastBlockTime() == block.timestamp);
    }

    receive() external payable {}
}

