        uint256 pastAfterFirst = c.pastBlockTime();
        uint256 balAfterFirst = address(c).balance;

        uint256 decidedPastBefore = c.pastBlockTime();
        uint256 decidedBalBefore = address(c).balance;

        bool reverted = false;
        (reverted, ) = address(c).call{value: amount}("");

        uint256 pastAfter = c.pastBlockTime();
        uint256 balAfter = address(c).balance;

        if (!firstOk) {
            assert(!reverted && pastAfterFirst == pastBefore && balAfterFirst == balBefore);
        } else if (doRevertCase) {
