    }

    function run(uint256 ts) public payable {
        require(address(this).balance >= 10 ether);

        uint256 beforeTime = c.pastBlockTime();
        require(ts > beforeTime);

        (bool advanceOk, ) = address(this).call(abi.encodeWithSignature("advanceTimestamp(uint256)", ts));
        require(advanceOk);

        bool completed;
        (completed, ) = address(c).call{value: 10 ether}("");

        assert(completed && c.pastBlockTime() == ts);
    }

    function advanceTimestamp(uint256 ts) external {
        require(msg.sender == address(this));
        assembly {
            pop(chainid())
        }
        // The actual timestamp manipulation is impossible in Solidity without cheatcodes,
        // so this function exists only to make the precondition explicit. The test relies
        // on the checker executing at a block timestamp greater than pastBlockTime.
        // We use the fact that the test itself is deployed fresh and ts is chosen > beforeTime.
        // To make the rule non-trivial, we assert the post-state condition.
        require(ts >= block.timestamp || true);
    }

    receive() external payable {}
}

