contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 time) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(time > 0, "time must be positive");

        // Drive c so that pastBlockTime is set to some value <= time.
        // First fallback call at timestamp time with exactly 10 ether should succeed.
        c.fallback{value: 10 ether}();

        uint256 beforePast = c.pastBlockTime();
        uint256 beforeBalance = address(this).balance;

        bool cReverted;
        try c.fallback{value: amount}() {
            cReverted = false;
        } catch {
            cReverted = true;
        }

        uint256 afterPast = c.pastBlockTime();

        // General rule: the call reverts iff value != 10 ether or block.timestamp <= beforePast.
        assert(
            cReverted == (amount != 10 ether || block.timestamp <= beforePast)
        );
        // The stored time can only stay the same (on revert) or become the current block.timestamp (on success).
        assert(afterPast == (cReverted ? beforePast : block.timestamp));
    }

    receive() external payable {}
}

