contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint64 targetTimestamp) public payable {
        require(address(this).balance >= amount);

        // Force the stored timestamp to a value we control through a successful fallback call.
        // Send exactly 10 ether with a very large timestamp argument is not directly possible;
        // instead we drive the state by making a valid call that sets pastBlockTime to the
        // current block timestamp.
        uint before = c.pastBlockTime();
        bool setupReverted;
        try c.fallback{value: 10 ether}() {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        uint stored = c.pastBlockTime();

        // The rule: a fallback call sending exactly 10 ether at a timestamp strictly greater
        // than the current stored pastBlockTime must complete and update pastBlockTime to the
        // current block timestamp; otherwise the call must revert and pastBlockTime must remain
        // whatever it was before (which, for this fresh deployment, is 0).
        uint expectedAfter;
        if (block.timestamp > stored) {
            expectedAfter = block.timestamp;
        } else {
            expectedAfter = stored;
        }

        bool secondReverted;
        try c.fallback{value: 10 ether}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            (secondReverted == (block.timestamp <= stored)) &&
            (secondReverted ? c.pastBlockTime() == stored : c.pastBlockTime() == expectedAfter)
        );
    }

    receive() external payable {}
}

