contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tsIncrement, uint256 value) public payable {
        // Read the current timestamp anchor before any state-changing call.
        uint256 beforeTime = c.pastBlockTime();

        // We need to be able to make a call with exactly 10 ether.
        // The value parameter is the candidate msg.value for the fallback call.
        require(address(this).balance >= value, "insufficient test balance");

        // The fallback requires block.timestamp > pastBlockTime.
        // To make a controlled timestamp condition, we cannot set block.timestamp,
        // so we construct two scenarios: the first is a call that must succeed
        // if value == 10 ether and the current timestamp is already greater than
        // pastBlockTime. We need to ensure the precondition for the success case.
        // Since a fresh c has pastBlockTime = 0 by default, a first call with
        // 10 ether will succeed. To make the rule generic over tsIncrement and value,
        // we first optionally make a successful advancing call if possible,
        // then test whether the fallback reverts or not.

        // Step 1: If we want to test a success, we need value == 10 ether and
        // block.timestamp > beforeTime. In a fresh run, beforeTime is likely 0,
        // so the success path is available if value == 10 ether.
        // Step 2: If value != 10 ether, the call must revert regardless of time.

        bool reverted;
        uint256 midTime;

        if (value == 10 ether) {
            // The first call should succeed if the current block.timestamp > beforeTime
            // (which is true for the very first call with a fresh c, since beforeTime is 0).
            // Use low-level call to catch revert without helper functions.
            (bool success, ) = address(c).call{value: value}("");
            reverted = !success;
            midTime = c.pastBlockTime();

            // General rule: when value is exactly 10 ether and the timestamp advances,
            // the call succeeds and pastBlockTime equals the current timestamp.
            assert(!reverted && midTime > beforeTime && midTime == block.timestamp);
        } else {
            // Any non-10-ether value must revert and leave pastBlockTime unchanged.
            (bool success, ) = address(c).call{value: value}("");
            reverted = !success;
            midTime = c.pastBlockTime();

            assert(reverted && midTime == beforeTime);
        }
    }

    receive() external payable {}
}

