contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        // precondition on amount is not needed beyond solvency for funding; but we will fund exactly amount
        require(address(this).balance >= amount);

        // read before-values
        uint beforeTime = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // deciding call: fallback with amount, as a top-level statement
        bool reverted;
        try c.call{value: amount}("") { reverted = false; } catch { reverted = true; }

        // read after-values
        uint afterTime = c.pastBlockTime();
        uint afterBal = address(c).balance;

        if (amount != 10 ether || block.timestamp <= beforeTime) {
            // expected revert: no timestamp update, no balance change
            assert(reverted && afterTime == beforeTime && afterBal == beforeBal);
        } else {
            // expected success: timestamp becomes now; balance change is +amount if no refund, or 0 if refunded
            assert(!reverted && afterTime == block.timestamp &&
                   (afterBal == beforeBal + amount || afterBal == 0));
        }
    }

    receive() external payable {}
}

