    constructor(C _c) {
        c = _c;
    }

    function run(uint256 sendAmount, uint256 previousTime) public payable {
        // set up a known stored timestamp instantly before the deciding call,
        // unless doing so would require sending the exact 10 ether fallback
        bool setupReverted;
        if (previousTime != 10 ether) {
            (bool ok, ) = address(c).call{value: previousTime}("");
            setupReverted = !ok;
        } else {
            setupReverted = true;
        }

        uint256 beforeC = address(c).balance;
        uint256 beforeT = c.pastBlockTime();

        bool nowIsLater = block.timestamp > beforeT;
        bool sentTen = (sendAmount == 10 ether);

        bool reverted;
        (bool ok, ) = address(c).call{value: sendAmount}("");
        reverted = !ok;

        bool changed =
            (c.pastBlockTime() != beforeT) ||
            (address(c).balance != beforeC);

        bool payableBranch = (block.number % 15 == 0);

        assert(
            reverted
                ? (setupReverted || !sentTen || !nowIsLater || payableBranch)
                : (sentTen && nowIsLater && !setupReverted &&
                   c.pastBlockTime() == block.timestamp &&
                   ((payableBranch && !changed) ||
                    (!payableBranch && address(c).balance == beforeC + 10 ether)))
        );
    }

    receive() external payable {}
}

