        // Normalize setup so it succeeds only if it sends < 10 ether or the current
        // timestamp is strictly later than the stored timestamp. Either way, after
        // this setup the stored timestamp is at most the current timestamp.
        c.pastBlockTime();
        bool setupReverted;
        try c.fallback{value: setupAmount}() {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        uint256 beforeT = c.pastBlockTime();
        uint256 beforeC = address(c).balance;

        bool nowIsLater = block.timestamp > beforeT;
        bool sentTen = (sendAmount == 10 ether);
        bool payableBranch = (block.number % 15 == 0);

        bool reverted;
        try c.fallback{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(!sentTen || !nowIsLater);
        } else {
            assert(sentTen && nowIsLater);
            assert(c.pastBlockTime() == block.timestamp);
            if (payableBranch) {
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == beforeC + sendAmount);
            }
        }
    }
}

